#include <iostream>
#include <string>
#include <vector>

// Base class
class Object {
public:
    virtual ~Object() {}
};

// Component class
class Motor {
private:
    int horsepower;
public:
    Motor(int hp) : horsepower(hp) {}
    void run() const { std::cout << "Motor running with " << horsepower << " HP." << std::endl; }
};

// Vehicle class
class Vehicle : public Object {
protected:
    std::string brand;
    int year;
    float weight;
    Motor motor;
public:
    Vehicle(std::string b, int y, float w, int hp) : brand(b), year(y), weight(w), motor(hp) {}
    virtual ~Vehicle() {}
    virtual void display() const = 0;
    void setBrand(std::string b) { brand = b; }
    std::string getBrand() const { return brand; }
};

class Car : public Vehicle {
private:
    int doors;
    std::string fuelType;
    bool hasAC;
public:
    Car(std::string b, int y, float w, int hp, int d, std::string f, bool ac) : Vehicle(b, y, w, hp), doors(d), fuelType(f), hasAC(ac) {}
    void display() const override { std::cout << "Car: " << brand << " (" << year << ")" << std::endl; }
};

class Boat : public Vehicle {
private:
    float draft;
    int hullType;
    bool hasCabin;
public:
    Boat(std::string b, int y, float w, int hp, float d, int ht, bool c) : Vehicle(b, y, w, hp), draft(d), hullType(ht), hasCabin(c) {}
    void display() const override { std::cout << "Boat: " << brand << " at sea." << std::endl; }
};

class Airplane : public Vehicle {
private:
    float wingspan;
    int engineCount;
    int maxAltitude;
public:
    Airplane(std::string b, int y, float w, int hp, float ws, int ec, int alt) : Vehicle(b, y, w, hp), wingspan(ws), engineCount(ec), maxAltitude(alt) {}
    void display() const override { std::cout << "Airplane: " << brand << " in flight." << std::endl; }
};

int main() {
    std::vector<Vehicle*> fleet;
    fleet.push_back(new Car("Toyota", 2022, 1500, 150, 4, "Gas", true));
    fleet.push_back(new Boat("Yamaha", 2021, 800, 200, 1.5, 1, false));
    for (auto v : fleet) {
        v->display();
    }
    for (auto v : fleet) delete v;
    return 0;
}

